
.dual-meters {
  padding-top: 6px;
}

.meter-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 0;
}

.meter-name {
  width: 34px;
  font-size: 11px;
  color: var(--c-text-dim);
  letter-spacing: 1px;
  flex-shrink: 0;
}

.meter-track {
  flex: 1;
  height: 5px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;

  &.affection {
    background: linear-gradient(90deg, #c47f2e, var(--c-affection));
  }

  &.desire {
    background: linear-gradient(90deg, #a83260, var(--c-desire));
  }
}

.meter-value {
  width: 30px;
  text-align: right;
  font-size: 11px;
  font-weight: 600;
  flex-shrink: 0;

  &.affection {
    color: var(--c-affection);
  }

  &.desire {
    color: var(--c-desire);
  }
}
